    public static void fun(int x, int a, int b, int c, int[] count) {
        if (a != x || b != x || c != x) {
            if (c != x) {
                if (a + b > x) {
                    c = x;
                } else {
                    c = a + b - 1;
                }
                count[0]++;
            }
            fun(x, c, a, b, count);
        }
